import{_ as t,o,c as a,ai as r}from"./chunks/framework.DQi1ytmF.js";const p=JSON.parse('{"title":"What craft adds to Angular","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts/vs-angular.md","filePath":"guide/concepts/vs-angular.md"}'),i={name:"guide/concepts/vs-angular.md"};function n(s,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="what-craft-adds-to-angular" tabindex="-1">What craft adds to Angular <a class="header-anchor" href="#what-craft-adds-to-angular" aria-label="Permalink to &quot;What craft adds to Angular&quot;">​</a></h1><p>Craft is not a replacement for Angular — it runs on Angular&#39;s DI, signals and router. This page is the honest list of what you get <strong>on top</strong>, and what it costs.</p><p>If you want the reasoning rather than the inventory, read <a href="/craft/guide/concepts/mental-model.html">The mental model</a>.</p><h2 id="the-compiler-catches-more" tabindex="-1">The compiler catches more <a class="header-anchor" href="#the-compiler-catches-more" aria-label="Permalink to &quot;The compiler catches more&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Angular</th><th>Craft</th></tr></thead><tbody><tr><td>Missing provider</td><td>runtime <code>NullInjectorError</code></td><td><strong>compile error</strong> at the route</td></tr><tr><td>Missing / misnamed component input</td><td>runtime, or silently <code>undefined</code></td><td><strong>compile error</strong> at the call site</td></tr><tr><td>Navigating to a route that doesn&#39;t exist</td><td>runtime 404</td><td><strong>compile error</strong></td></tr><tr><td>Missing route param</td><td>runtime</td><td><strong>compile error</strong></td></tr><tr><td>Unhandled declared failure</td><td>nothing — you find out in production</td><td><strong>compile error</strong> (exhaustiveness)</td></tr><tr><td>Handling a failure that can&#39;t happen</td><td>dead code nobody notices</td><td><strong>compile error</strong></td></tr><tr><td>Forgetting to mock a dependency in a test</td><td>test passes for the wrong reason</td><td><strong>compile error</strong></td></tr><tr><td>A template stops rendering an element</td><td>silent</td><td><strong>compile error</strong>, if asserted</td></tr></tbody></table><p>That column is the whole point. Everything below exists to make it possible.</p><h2 id="dependencies-are-visible-in-the-type" tabindex="-1">Dependencies are visible in the type <a class="header-anchor" href="#dependencies-are-visible-in-the-type" aria-label="Permalink to &quot;Dependencies are visible in the type&quot;">​</a></h2><p><code>inject(X)</code> hides the graph: nothing in a consumer&#39;s type says <code>X</code> is needed. <code>yield* X()</code> puts it in the type, which is what lets the route check, the test register and the dependency snapshot all read the same source of truth.</p><p>You can also yield <strong>part</strong> of a service — <code>yield* X.someProperty()</code> — so the graph records exactly what you used, and a test provides exactly that.</p><h2 id="state-primitives-not-patterns" tabindex="-1">State primitives, not patterns <a class="header-anchor" href="#state-primitives-not-patterns" aria-label="Permalink to &quot;State primitives, not patterns&quot;">​</a></h2><p>Angular gives you <code>signal</code>, <code>computed</code>, <code>resource</code> and leaves the composition to you. Craft ships five primitives with one shape — <a href="/craft/guide/concepts/choose-primitive.html"><code>state</code>, <code>query</code>, <code>mutation</code>, <code>queryParams</code>, <code>asyncProcess</code></a> — each carrying its own status, exceptions and derived values.</p><ul><li><strong>URL state as a primitive.</strong> <code>queryParams</code> makes the query string the source of truth, with typed codecs. No <code>ActivatedRoute</code> subscription, no synchronisation effect.</li><li><strong>Declarative read/write links.</strong> <code>insertReactOnMutation</code> connects a mutation to the queries it invalidates, including optimistic updates with automatic rollback — instead of calling <code>refetch()</code> from the call site.</li><li><strong>Composable behaviour.</strong> Insertions (storage persistence, pagination placeholders, entity collections) are plain functions of the same shape as the ones you write.</li></ul><h2 id="services-are-functions" tabindex="-1">Services are functions <a class="header-anchor" href="#services-are-functions" aria-label="Permalink to &quot;Services are functions&quot;">​</a></h2><p>A <code>craftService</code> is a factory with a name and a scope: no class, no decorator, no constructor. Scopes are explicit (<code>function</code>, <code>toProvide</code>, <code>global</code>, <code>manuallyProvidedAtRoot</code>, <code>abstract</code>) rather than inferred from where you happened to put <code>providedIn</code>.</p><p><code>abstract</code> services turn &quot;who implements this&quot; into a decision of the mounting site — a route, a feature config, a test — with the compiler enforcing that someone did.</p><h2 id="components-are-functions" tabindex="-1">Components are functions <a class="header-anchor" href="#components-are-functions" aria-label="Permalink to &quot;Components are functions&quot;">​</a></h2><ul><li>Inputs and outputs are <strong>factory parameters</strong>, so binding errors are type errors.</li><li>Templates are TypeScript: <code>each</code>, <code>ifBlock</code>, <code>matchBlock</code>, <code>defer</code> instead of <code>@for</code> / <code>@if</code> / <code>@switch</code> / <code>@defer</code>. <code>matchBlock.exhaustive</code> is stricter than <code>@switch</code> — a missing case doesn&#39;t compile.</li><li>No host element is inserted. Styles are scoped with CSS <code>@scope</code>, <code>:scope</code> being the component&#39;s own root.</li><li><strong>Directives compose with <code>.pipe(...)</code></strong> and decorate <em>both</em> the logic factory and the template, so behaviour and markup travel together.</li><li><strong>Content projection is a rendering context</strong>, not a component category, with DOM contracts (<code>RequiredContent</code>) checked statically.</li></ul><h2 id="exceptions-are-values" tabindex="-1">Exceptions are values <a class="header-anchor" href="#exceptions-are-values" aria-label="Permalink to &quot;Exceptions are values&quot;">​</a></h2><p>A declared failure is a <code>craftException</code> <strong>returned</strong>, not thrown — so it flows through types instead of escaping through the stack.</p><ul><li>Read them by origin: <code>exceptions().params</code> (rejected before the request) vs <code>exceptions().loader</code> (produced by it).</li><li>A component&#39;s unhandled codes flow up into its route&#39;s union.</li><li><code>assertExhaustiveRouteExceptions(routes)</code> proves every reachable code is handled, and that no handler is dead.</li></ul><p>Errors — the unexpected kind — stay separate and reach the global error component. See <a href="/craft/guide/concepts/exceptions.html">Exceptions as values</a>.</p><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h2><ul><li>Type-safe navigation, params and query params.</li><li><strong>Non-blocking navigation</strong>: the URL commits immediately and a pending component appears only if the wait is real, with a stay → blank → loader timeline you configure.</li><li>Route-scoped providers built from the route&#39;s <strong>own</strong> params, data and guarded values.</li><li><code>withRetry</code> on lazy chunks, plus a dedicated route-load-error path for a stale deploy or a flaky network — the failure mode where Angular gives you a dead navigation.</li><li>Guards are bare generators, composable and parameterisable.</li></ul><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li>Registers derived from the real dependency graph: forgetting a mock is a compile error.</li><li><code>boundaryOnly</code> keeps the whole app graph real and mocks only what touches the platform, so a passing test means something.</li><li>Components split into a logic test (no DOM) and a template test (no factory).</li><li><a href="/craft/guide/testing/type-level.html">Type-level tests</a> assert the template contract itself — that an element renders only under a condition, that a binding is the one you think.</li><li><a href="/craft/guide/testing/architecture.html">Architecture rules</a> assert the shape of the app on the static Craft graph — exclusive features, unique HTTP, <code>craftUnique</code>, and armed route DI proofs. That graph is not Nx&#39;s project graph; see <a href="/craft/guide/testing/craft-graph-vs-nx.html">Craft graph vs Nx</a>.</li></ul><h2 id="because-it-s-declarative-you-get-observability-for-free" tabindex="-1">Because it&#39;s declarative, you get observability for free <a class="header-anchor" href="#because-it-s-declarative-you-get-observability-for-free" aria-label="Permalink to &quot;Because it&#39;s declarative, you get observability for free&quot;">​</a></h2><p>This one is a consequence rather than a feature. Because every dependency resolution, every primitive and every crafted function goes through one system, that system is also where you can wrap them all:</p><ul><li>structured logging through a yieldable <code>Console</code> you can override once;</li><li>correlation ids propagated across the graph;</li><li>app snapshots of the live dependency tree;</li><li>per-service timing and tracing, via <code>provideServiceYieldWrapper</code> / <code>provideFnWrapper</code>, without touching business code.</li></ul><p>Retrofitting that onto imperative code means instrumenting every call site. Here it is one provider. See <a href="/craft/guide/advanced/observability.html">Observability</a>.</p><p>The same property is what makes an app <strong>legible to a machine</strong> — an agent, or a future WebMCP-style integration — because the dependency graph, the reachable exceptions and the route contract are all declared data rather than control flow to be inferred.</p><h2 id="tooling" tabindex="-1">Tooling <a class="header-anchor" href="#tooling" aria-label="Permalink to &quot;Tooling&quot;">​</a></h2><ul><li><code>craft route add</code> / <code>craft route split</code> scaffold typed routes; the output is ordinary editable TypeScript.</li><li>ESLint rules that enforce the architecture and autofix most of it (<code>no-angular-inject</code>, <code>prefer-craft-service</code>, <code>prefer-craft-http-client</code>, <code>require-cascade-route-di-check</code>, …).</li><li>Codemods to migrate an existing Angular app progressively.</li></ul><h2 id="what-it-costs" tabindex="-1">What it costs <a class="header-anchor" href="#what-it-costs" aria-label="Permalink to &quot;What it costs&quot;">​</a></h2><p>Being fair about the trade:</p><ul><li><strong>A new vocabulary.</strong> Generators, insertions, scopes and yields are unfamiliar before they are useful.</li><li><strong>Type-checking time.</strong> Deep inference is not free; large route collections need splitting (<a href="/craft/guide/routing/scaling.html">Scaling routes</a>).</li><li><strong>Unused proofs compile.</strong> The route DI checks are type aliases TypeScript does not require you to keep. <a href="/craft/guide/testing/architecture.html#assertroutediproofs">Architecture tests</a> make omitting them a hard failure.</li><li><strong>Error messages.</strong> A failed inference deep in a type can read badly.</li><li><strong>Experimental.</strong> The library and this documentation both still move between minor versions — see the <a href="/craft/resources/migration.html">migration notes</a>.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/craft/guide/concepts/mental-model.html">The mental model</a></li><li><a href="/craft/learn/">Learn: the guided path</a></li><li><a href="/craft/guide/concepts/choose-primitive.html">Which primitive should I use?</a></li></ul>',37)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
